package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import java.util.*;
import java.sql.SQLException;
import java.time.Instant;
/** Fixed-field, aggregate support export. Never serializes environment properties or business rows. */
final class OperatorDiagnostics {
 private OperatorDiagnostics(){}
 static Map<String,Object> inspect(Store store,Store.Db db)throws SQLException{
  Service.requireAccountAdministrator(db,db.viewerId);long now=System.currentTimeMillis();var queue=new LinkedHashMap<>(QueueHealth.inspect(store,db,now));queue.remove("counts");var scans=new LinkedHashMap<String,Object>();for(String state:List.of("pending","clean","infected","unavailable"))scans.put(state,db.count("SELECT COUNT(*) FROM os_attachment_scan WHERE status=?",state));scans.put("held",db.count("SELECT COUNT(*) FROM os_attachment WHERE quarantined=1"));scans.put("untracked",db.count("SELECT COUNT(*) FROM os_attachment a WHERE NOT EXISTS (SELECT 1 FROM os_attachment_scan s WHERE s.attachment_id=a.sys_id)"));
  var migrations=new LinkedHashMap<String,Object>();String status=db.postgres?"detail::jsonb->>'status'":"json_extract(detail,'$.status')";for(String state:List.of("fetching","review","applied","cutover","cancelled"))migrations.put(state,db.count("SELECT COUNT(*) FROM os_transfer_job WHERE "+status+"=?",state));migrations.put("total",db.count("SELECT COUNT(*) FROM os_transfer_job"));long installed=db.count("SELECT COALESCE(MAX(version),0) FROM os_migration");var flags=new LinkedHashMap<String,Object>();for(String key:List.of("WORK_ENABLED","ATTACHMENT_SCANNING_ENABLED","AI_ENABLED","AI_SUPPORT_ENABLED"))flags.put(key,store.environment.getProperty(key,Boolean.class,false));
  return map("format","openservice-diagnostics-v1","captured_at",Instant.ofEpochMilli(now).toString(),"runtime",map("java",System.getProperty("java.version"),"spring_boot",org.springframework.boot.SpringBootVersion.getVersion()),"database",map("engine",store.postgres?"PostgreSQL":"SQLite","schema_installed",installed,"schema_expected",Migrations.VERSION,"schema_matches",installed==Migrations.VERSION),"flags",flags,"preflight",DeploymentPreflight.inspect(store,db),"queue",queue,"attachments",scans,"migrations",migrations,"retention",map("support_conversations",db.count("SELECT COUNT(*) FROM os_support_conversation"),"expired_support_conversations",db.count("SELECT COUNT(*) FROM os_support_conversation WHERE updated_at<?",SupportConversations.cutoff()),"report_measurements",db.count("SELECT COUNT(*) FROM os_report_measurement")),"limitations",List.of("Local aggregate snapshot, not an uptime, security or production-readiness certification.","Enabled workers, AI and scanners are configuration observations, not external service connectivity or quality checks.","Verify real TLS, email delivery, backup restoration, dependency advisories and operational ownership separately.","No credentials, business content, identifiers or raw logs are included; review this operational metadata before sharing."));
 }
}
